import json

# Try keeping only the largest object (by area)
def keep_largest_object(grid):
    bg = 8
    best_color = None
    best_size = 0

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg and grid[r][c] == best_color:
                continue  # Already counted this color
            elif grid[r][c] != bg:
                # New color
                size = sum(1 for row in grid for cell in row if cell == grid[r][c])
                if size > best_size:
                    best_size = size
                    best_color = grid[r][c]

    if best_color is None:
        return [[bg] * len(grid[0]) for _ in range(len(grid))]

    output = [[bg] * len(grid[0]) for _ in range(len(grid))]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == best_color:
                output[r][c] = best_color

    return output

