import json

# Try shifting all objects up by 1 row (keeping them in same column positions)
def shift_up(grid):
    rows = len(grid)
    cols = len(grid[0])
    bg = 8

    output = [[bg] * cols for _ in range(rows)]

    for r in range(1, rows):
        for c in range(cols):
            if grid[r-1][c] != bg:
                output[r][c] = grid[r-1][c]

    return output

print(json.dumps({"action": "submit", "grid": shift_up(test_input)}))

